let cw, ch
let S, T
let C1, C2
let texture
let painter
let palettes = [
  ["#f94144", "#f3722c", "#f9c74f", "#90be6d", "#43aa8b", "#577590"],
  ["#ffe03d", "#fe4830", "#d33033", "#6d358a", "#1c509e", "#00953c"],
  ["#ffffff", "#00a7e1", "#00171f", "#003459", "#007ea7"],
  ["#00b2b4", "#fdd35b", "#3b4696", "#f4737d", "#333333"],
  ["#ff595e", "#ffca3a", "#8ac926", "#1982c4", "#6a4c93"],
	["#283044", "#78a1bb", "#ebf5ee", "#bfa89e", "#8b786d"],
  ["#00916e", "#feefe5", "#ffcf00", "#ee6123", "#fa003f"],
  ["#1c1c1c", "#696969", "#daddd8", "#fafaff"],
  ["#ccc5b9", "#403d39", "#252422", "#6a040f"],
  ["#233d4d", "#fe7f2d", "#fcca46", "#619b8a"],
  ["#edae49", "#d1495b", "#00798c"],
  ["#bdd9bf", "#2e4052", "#ffc857"],
]
let palette
let sizeRange = [50, 250]

function setup () {
  cw = windowWidth
  ch = windowHeight
  createCanvas(cw, ch)
	pixelDensity(1)
  texture = granulate(100)
  colorMode(HSB)

  background('#f0f0f0')
  image(texture, 0, 0, cw, ch)

  palette = random(palettes)
  painter = createPainter()
}

function draw () {
  let done = painter.next().done
  if (done) {
    noLoop()
  }
}

function *createPainter () {
  noStroke()
  let start = random(...sizeRange)
  let columnIndex = 0
  for (let i = -start; i < cw + sizeRange[1];) {
    S = round(random(...sizeRange))
    T = S / sqrt(3)
    A = atan(2*T/S)
    let startY = -random(T, 2*T)
    let nextSize
    let index = 0
    for (let j = 0; j < ch + 2*T;) {
      nextSize = floor(random(1, 4))
      let a = index
      let b = index + nextSize
      let x2 = i + S
      let y2 = floor(a / 2) * 2 * T + startY
      let x1 = i
      let y1 = (a % 2 === 0) ? y2: y2 + 2 * T

      let x3 = i + S
      let y3 = floor(b / 2) * 2 * T + startY
      let x4 = i
      let y4 = (b % 2 === 0) ? y3: y3 + 2 * T

      let points = shiftPoints([[x1, y1], [x2, y2], [x3, y3], [x4, y4]], [-x1, -y1])

      push()
      translate(x1, y1)
      shearY(PI/6) // Enable

      let hue = random(360)

      C2 = random(palette)
      C1 = random(palette)
      let _wG_1 = 0; while ((C1 === C2) && ++_wG_1 < 20000) {
        C1 = random(palette)
      }

      fill(C1 + '40')

      quad(...points.flat())
      patternColors([C2, C1])
      pattern(PTN.noiseGrad(0.9))
      // pattern(PTN.stripe(max((S / 60), 3)))
      if (a % 2 === 0 && nextSize === 2) {
        drawBauhausTile(S, 2 * T, points)
      } else if (a % 2 === 1 && nextSize === 2) {
        drawBauhausTile2(S, 2 * T, points)
      } else if (a % 2 === 0 && nextSize === 3) {
        drawBauhausTile3(S, 2 * T, points)
      } else if (a % 2 === 1 && nextSize === 3) {
        // Reverse
        let newPoints = [points[2], points[3], points[0], points[1]]
        drawBauhausTile3(S, 2 * T, newPoints, true)
      } else if (a % 2 === 0 && nextSize === 1) {
        drawBauhausTile4(S, 2 * T, points)
      } else if (a % 2 === 1 && nextSize === 1) {
        push()
        translate(S, 0) // This is wrong but a nice mistake. Probably fix later
        rotate(PI)
        drawBauhausTile4(S, 2 * T, points)
        pop()
      }
      pop()

      j = y1
      index += nextSize
      yield 1
    }
    columnIndex++
    i = i + S
  }
}

let shiftPoints = (points, delta) => {
  return points.map(p => [p[0] + delta[0], p[1] + delta[1]])
}

let drawBauhausTile4 = (w, h, points) => {
  push()
  let type = random(['A', 'B', 'C', 'D'])
  switch (type) {
    case 'A':
      rectPattern(0, 0, w/2, h/2)
      break
    case 'B':
      arcPattern(0, 0, w, h, 0, PI/2)
      break
    case 'C':
      if (random() < 0.5) {
        trianglePattern(0, 0, w, 0, w/2, h/2)
      } else {
        trianglePattern(0, 0, w/2, h/2, 0, h)
      }
      break
    case 'D':
      quadPattern(...points.flat())
      break
  }
  pop()
}

let drawBauhausTile3 = (w, h, points, inverted = false) => {
  let type = random(['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H'])
  let sw = random(1, 1.5)
  let sh = random(0.6, 0.8)
  let mul = inverted ? -1 : 1
  let dy = h * (1 - sh) * mul
  let midPoint
  let pt2 = [points[2][0], points[2][1] - dy]
  let pt3 = [points[3][0], points[3][1] - dy]
  switch (type) {
    case 'A':
      for (let i = 0; i < 6; i+=2) {
        let p1 = lerpPoint(points[0], points[1], i/6)
        let p2 = lerpPoint(points[0], points[1], i/6 + sw/6)
        let r1 = lerpPoint(pt3, pt2, i/6)
        let r2 = lerpPoint(pt3, pt2, i/6 + sw/6)
        quadPattern(...p1, ...p2, ...r2, ...r1)
      }
      break
    case 'B':
      let n = floor(random(2, 4))
      //let tr = lerpColor(color(C1), color('#FFFFFF00'), 0.5)
			let tr = C1
      sw = w / n / 2
      let m = 2 * n + 1
      sh = sw * sqrt(2)
      for (let i = 0; i < m/2; i++) {
        patternColors(i % 2 === 0 ? [C2, tr] : [tr, C2])
        pattern(PTN.noiseGrad(i % 2 === 0 ? 0.9 : 0.45))
        let p1 = lerpPoint(points[0], points[1], i/m)
        let p2 = lerpPoint(points[0], points[1], (m-i) / m)
        let q1 = [points[3][0], points[3][1] - sh * i * mul]
        let q2 = [points[2][0], points[2][1] - sh * i * mul]
        let r1 = lerpPoint(q1, q2, i/m)
        let r2 = lerpPoint(q1, q2, (m-i) / m)
        quadPattern(...p1, ...p2, ...r2, ...r1)
      }
      break
    case 'C':
      if (random() < 0.5) {
        trianglePattern(...points[0], ...points[1], ...points[2])
      } else {
        trianglePattern(...points[0], ...points[2], ...points[3])
      }
      let pts = lerpShape(points, 0.25, w * mul)
      patternColors([C1, C2])
      quadPattern(...pts.flat())
      break
    case 'D':
      midPoint = lerpPoint(points[1], points[2], 0.5)
      let d1 = midPoint[1] - points[1][1]
      if (inverted) {
        arcPattern(...midPoint, w*2, d1*2, -PI/2, PI/2)
      } else {
        arcPattern(...midPoint, w*2, d1*2, PI/2, 3*PI/2)
      }
      break
    case 'E':
      midPoint = lerpPoint(points[0], points[3], 0.5)
      let d2 = midPoint[1] - points[0][1]
      if (inverted) {
        arcPattern(...midPoint, w*2, d2*2, PI/2, 3*PI/2)
      } else {
        arcPattern(...midPoint, w*2, d2*2, -PI/2, PI/2)
      }
      break
    case 'F':
      let pf1 = lerpPoint(points[0], points[1], 1/3)
      let pf2 = lerpPoint(points[0], points[1], 2/3)
      let pf3 = lerpPoint(points[3], points[2], 1/3)
      let pf4 = lerpPoint(points[3], points[2], 2/3)
      quadPattern(...pf1, ...pf2, ...pf4, ...pf3)
      break
    case 'G':
      let pg1 = lerpPoint(points[0], points[1], 1/3)
      let pg2 = lerpPoint(points[0], points[1], 2/3)
      let pg3 = lerpPoint(points[3], points[2], 1/3)
      let pg4 = lerpPoint(points[3], points[2], 2/3)
      quadPattern(...points[0], ...pg1, ...pg3, ...points[3])
      quadPattern(...pg2, ...points[1], ...points[2], ...pg4)
      break
    case 'H':
      quadPattern(...points.flat())
      break
  }
}

let lerpShape = (points, t, w) => {
  let s = w*t
  let p1 = lerpPoint(points[0], points[1], t)
  let p2 = lerpPoint(points[0], points[1], 1 - t)
  let p3 = lerpPoint(points[3], points[2], t)
  let p4 = lerpPoint(points[3], points[2], 1 - t)
  let p5 = [p1[0], p1[1] + s]
  let p6 = [p2[0], p2[1] + s]
  let p7 = [p3[0], p3[1] - s]
  let p8 = [p4[0], p4[1] - s]
  return [p5, p6, p8, p7]
}

let drawBauhausTile2 = (w, h) => {
